// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }
    function testFuzz_property(uint56 _changeFee, uint16 _feeRate) public {
        vm.assume(_feeRate <= 5000);
        vm.assume(_changeFee != _feeRate);
        vm.prank(address(0));
        try c.initialize(
            address(0),
            address(0),
            0,
            0,
            _changeFee,
            _feeRate,
            bytes32(0),
            false,
            false
        ) {} catch {}
        assertEq(c.feeRate(), _feeRate);
    }
}
